use std::fs;
fn replace(s:&mut String,old:&str,new:&str){assert_eq!(s.matches(old).count(),1,"missing/duplicate {old}");*s=s.replace(old,new);}
fn main(){let r="/home/ubuntu/src/zopro-perf-work/g2-denominator-record176";let mut s=fs::read_to_string("/home/ubuntu/src/zopro-perf-work/loose-complex-caller176/review.rs").unwrap().replace("loose-complex-caller176","g2-denominator-record176").replace("zopro_loose_complex_square","zopro_g2_cached_denominator").replace("129","130");
 let start=s.find("let edits=load").unwrap();let end=s[start..].find("let ids=load").unwrap()+start;
 s.replace_range(start..end,r#"let edits=load(format!("{R}/edits.json"));let manifest=load(format!("{Z}/docs/benchmarks/2026-10-30-g2-vector-sign-adoption176/artifacts/production-source-manifest.json"));let original=manifest["source_files_sha256"].as_object().unwrap();assert_eq!(original.len(),176);let mut exact=0;
for(p,h)in original{assert_eq!(sha(Path::new(Z).join(p)),h.as_str().unwrap());let mut bytes=fs::read(Path::new(R).join("source").join(p)).unwrap();if format!("{:x}",Sha256::digest(&bytes))==h.as_str().unwrap(){exact+=1;}if let Some(suffix)=edits["parents"].get(p){let suffix=suffix.as_str().unwrap().as_bytes();assert!(bytes.ends_with(suffix));bytes.truncate(bytes.len()-suffix.len());}let local=edits["replacements"].as_array().unwrap().iter().filter(|e|e["path"]==*p).collect::<Vec<_>>();if !local.is_empty(){let mut text=String::from_utf8(bytes).unwrap();for e in local.into_iter().rev(){let new=e["new"].as_str().unwrap();assert_eq!(text.matches(new).count(),1);text=text.replace(new,e["old"].as_str().unwrap());}bytes=text.into_bytes();}assert_eq!(format!("{:x}",Sha256::digest(bytes)),h.as_str().unwrap());if p.starts_with("crates/zopro-bn254/"){assert_eq!(sha(Path::new(R).join("source").join(p)),h.as_str().unwrap());}}assert_eq!(exact,172);
let mut adapter=fs::read_to_string(edits["adapter_original"].as_str().unwrap()).unwrap();for old in["std::mem::size_of::<[FqBatch; 2]>()","std::mem::size_of::<[FqBatch;2]>()"]{assert_eq!(adapter.matches(old).count(),1);adapter=adapter.replace(old,"std::mem::size_of::<G2PrefixRecord>()");}assert_eq!(adapter,fs::read_to_string(format!("{R}/caller_probe.rs")).unwrap());assert_eq!(adapter,fs::read_to_string(format!("{R}/source/crates/zopro-core/src/msm/caller_probe.rs")).unwrap());
"#);
 let start=s.find("let code=load").unwrap();let end=s[start..].find("let jobs=load").unwrap()+start;
 s.replace_range(start..end,r#"let code=load(format!("{R}/codegen.json"));assert_eq!(code.as_array().unwrap().len(),3);for c in code.as_array().unwrap(){let text=fs::read_to_string(c["file"].as_str().unwrap()).unwrap();assert_eq!(text.matches("vpmadd52").count()as u64,c["static_IFMA_sites"].as_u64().unwrap());let count=text.lines().filter(|line|{let Some((a,_))=line.split_once(':')else{return false};!a.trim().is_empty()&&a.trim().as_bytes().iter().all(|c|c.is_ascii_hexdigit())}).count();assert_eq!(count as u64,c["instruction_lines"].as_u64().unwrap());assert_eq!(sha(c["file"].as_str().unwrap()),c["sha256"].as_str().unwrap());}
"#);
 replace(&mut s,"let signature=json!([v[\"output_sha256\"],v[\"capacity_bytes_per_worker\"],v[\"fixture_reference_bytes_per_worker\"]]);",r#"let size=v["size"].as_u64().unwrap();let fields=if arm=="on"{4}else{2};let cap=v["capacity_bytes_per_worker"].as_u64().unwrap();assert!(cap>=size/8*fields*320&&cap<=size/8*9*320);let signature=json!([v["output_sha256"],v["fixture_reference_bytes_per_worker"]]);"#);
 replace(&mut s,"assert_eq!(failures.len(),4);assert_eq!(analysis[\"component_gate_passed\"],false);","assert_eq!(analysis[\"component_gate_passed\"],failures.is_empty());");
 replace(&mut s,"assert_eq!(a[\"qualified\"],qualified);assert!(qualified);profiles.push", "assert_eq!(a[\"qualified\"],qualified);profiles.push");
 replace(&mut s,"\"private_originals_exact\":171,\"all176recover\":true,\"qualified_field_helper_exact\":true,\"original_OFF_expression_verbatim\":true", "\"private_originals_exact\":172,\"all176recover\":true,\"all17field_sources_exact\":true,\"original_OFF_expressions_verbatim\":true,\"capacities_variant_specific_within_original_allowance\":true");
 replace(&mut s,"\"component_gate_passed\":false,\"failed_checks\":failures", "\"component_gate_passed\":failures.is_empty(),\"failed_checks\":failures");
 replace(&mut s,"four aggregate gain failures;zero proofs", "all gates reconstructed;zero proofs");
 fs::write(format!("{r}/review.rs"),s).unwrap();println!("Prepared independent denominator-record reviewer; exact inverse source/adapter edits and per-arm capacity bounds; no timing");}
